-- =====================================================================
--  CATÁLOGO DE PROYECTOS (ordenado de mayor a menor importancia)
--  Pegalo en Supabase > SQL Editor > New query y ejecutalo.
--
--  Requiere haber ejecutado antes proyectos-datos.sql (columnas nuevas).
--  - Los proyectos que ya existen (se buscan por nombre) conservan su
--    contenido: solo se les asigna categoría, estado, destacado y posición.
--    Excepción: BBRAS, DriveNow Car, Nemesis Solutions y Chau Naranja
--    reciben descripción y etiquetas nuevas (sus enlaces se conservan).
--  - Los que no existen se agregan.
--  - No borra nada. Es seguro repetirlo.
-- =====================================================================

-- Antes existía la categoría «Juegos»: ahora es un tipo dentro de Escritorio o Web.
update projects
set subcategory = coalesce(subcategory, 'Juegos'), category = 'escritorio'
where category = 'juegos';

do $catalogo$
declare
  item jsonb;
  found_id bigint;
