,"links":[{"label":"⌥ GitHub","url":"https://github.com/Brunitoa10/Candy_Crush"}],"category":"escritorio","subcategory":"Juegos","status":"desarrollo","featured":false,"overwrite":true,"keep_links":false,"sort":19},{"matches":["Super Marios Bros","Super Marios Bros"],"name":"Super Marios Bros","icon":"👨🏽‍💻","description":"Versión mejorada del clásico con arquitectura modular y nuevos desafíos.","tags":[{"label":"Java","accent":"green"},{"label":"Patrones de diseño","accent":"cyan"},{"label":"SOLID","accent":"green"},{"label":"Clean code","accent":"cyan"}],"links":[{"label":"⌥ code","url":"https://github.com/Brunitoa10/SuperMarioBros"}],"category":"escritorio","subcategory":"Juegos","status":"completado","featured":false,"overwrite":false,"keep_links":false,"sort":20},{"matches":["2048","2048"],"name":"2048","icon":"👨🏽‍💻","description":"El 2048 es un juego de puzzle y estrategia cuyo objetivo es lanzar y combinar bloques numerados.","tags":[{"label":"ReactJS","accent":"green"},{"label":"Prolog","accent":"cyan"}],"links":[{"label":"⌥ code","url":"https://github.com/Brunitoa10/2048"}],"category":"web","subcategory":"Juegos","status":"completado","featured":false,"overwrite":false,"keep_links":false,"sort":21},{"matches":["GitHub","GitHub"],"name":"GitHub","icon":"📡","description":"Herramienta de monitoreo de red para la planta industrial de Bunge. Visualiza topología en tiempo real, detecta dispositivos caídos y genera alertas. Stack Python + Bash + Java + HTML. Portfolio piece & utility real.","tags":[{"label":"Python","accent":"green"},{"label":"Bash","accent":"green"},{"label":"Networking","accent":"cyan"},{"label":"Java","accent":"cyan"},{"label":"HTML","accent":"green"}],"links":[{"label":"⌥ GitHub","url":"https://github.com/Brunitoa10"}],"category":"infra","subcategory":"Monitoreo","status":"produccion","featured":false,"overwrite":false,"keep_links":false,"sort":22},{"matches":["Topología de Red — Bunge BB","Topología de Red — Bunge BB"],"name":"Topología de Red — Bunge BB","icon":"🗺️","description":"Documentación visual completa de la infraestructura: NOC, oficinas, piso de producción, calado de camiones y garita. Vista técnica y para usuarios finales.","tags":[{"label":"draw.io","accent":"cyan"},{"label":"Networking","accent":"green"},{"label":"Documentación","accent":"cyan"}],"links":[],"category":"infra","subcategory":"Documentación","status":"completado","featured":false,"overwrite":false,"keep_links":false,"sort":23},{"matches":["Monitor de equipos en red"],"name":"Monitor de equipos en red","icon":"🖥️","description":"Herramienta en PowerShell puro que monitorea equipos de red: dispositivos cargados desde JSON por sede y tipo, colores según pérdida de paquetes y registro de caídas con fecha, hora y duración. Portable, sin instalación.","tags":[{"label":"PowerShell","accent":"green"},{"label":"Redes","accent":"cyan"},{"label":"JSON","accent":"green"},{"label":"Portable","accent":"cyan"}],"links":[],"category":"infra","subcategory":"Monitoreo","status":"desarrollo","featured":false,"overwrite":true,"keep_links":false,"sort":24},{"matches":["prometeo","prometeo"],"name":"prometeo","icon":"🔥","description":"Repo personal de herramientas IT. Scripts de automatización, utilidades de red y diagnóstico para entornos de campo. Filosofía: production-ready desde el día uno.","tags":[{"label":"Python","accent":"green"},{"label":"Bash","accent":"green"},{"label":"Open Source","accent":"cyan"}],"links":[{"label":"⌥ GitHub","url":"https://github.com/TU_USUARIO/prometeo"}],"category":"infra","subcategory":"Automatización","status":"completado","featured":false,"overwrite":false,"keep_links":false,"sort":25},{"matches":["Kali Security Lab","Kali Security Lab"],"name":"Kali Security Lab","icon":"🔐","description":"Lab de hacking ético parrot - kali linux. Configuración de theHarvester, Sherlock, recon-ng, Kismet y macchanger para OSINT y análisis de red.","tags":[{"label":"Kali","accent":"green"},{"label":"Docker","accent":"cyan"},{"label":"OSINT","accent":"green"}],"links":[],"category":"infra","subcategory":"Seguridad","status":"completado","featured":false,"overwrite":false,"keep_links":false,"sort":26},{"matches":["Cuenta Bancaria","Cuena Bancaria","Cuena Bancaria"],"name":"Cuenta Bancaria","icon":"👨🏽‍💻","description":"Operaciones como depósitos, retiros y transferencias.","tags":[{"label":"Java","accent":"green"},{"label":"Polimorfismo","accent":"cyan"},{"label":"Herencia","accent":"green"},{"label":"Generalizacion","accent":"cyan"}],"links":[{"label":"⌥ code","url":"https://github.com/Brunitoa10/CuentaBancaria"}],"category":"escritorio","subcategory":"Académico","status":"completado","featured":false,"overwrite":false,"keep_links":false,"sort":27},{"matches":["Cuenta Palabras","Cuenta Palabras"],"name":"Cuenta Palabras","icon":"👨🏽‍💻","description":"Cuenta repeticiones de palabras y palabras más usadas.","tags":[{"label":"C","accent":"green"},{"label":"Headers","accent":"cyan"},{"label":"multiset","accent":"green"}],"links":[{"label":"⌥ code","url":"https://github.com/Brunitoa10/CuentaPalabras"}],"category":"escritorio","subcategory":"Académico","status":"completado","featured":false,"overwrite":false,"keep_links":false,"sort":28},{"matches":["Gestión de Directorios","Gestion de Directorios","Gestion de Directorios"],"name":"Gestión de Directorios","icon":"👨🏽‍💻","description":"Carpeta Documentos de Windows.","tags":[{"label":"Java","accent":"green"},{"label":"Estructuras de datos","accent":"cyan"}],"links":[{"label":"⌥ code","url":"https://github.com/Brunitoa10/Gestion_de_Directorios"}],"category":"escritorio","subcategory":"Académico","status":"completado","featured":false,"overwrite":false,"keep_links":false,"sort":29}]'::jsonb)
  loop
    select id into found_id
    from projects
    where lower(name) in (select lower(value) from jsonb_array_elements_text(item->'matches'))
    order by id
    limit 1;

    if found_id is null then
      insert into projects (name, icon, description, tags, links, category, subcategory, status, wide, sort_order)
      values (
        item->>'name', item->>'icon', item->>'description', item->'tags', item->'links',
        item->>'category', item->>'subcategory', item->>'status', (item->>'featured')::boolean, (item->>'sort')::int
      );
    else
      update projects set
        name       = item->>'name',
        category   = item->>'category',
        subcategory = item->>'subcategory',
        status     = item->>'status',
        wide       = (item->>'featured')::boolean,
        sort_order = (item->>'sort')::int,
        icon        = case when (item->>'overwrite')::boolean then item->>'icon' else icon end,
        description = case when (item->>'overwrite')::boolean then item->>'description' else description end,
        tags        = case when (item->>'overwrite')::boolean then item->'tags' else tags end,
        links       = case when (item->>'overwrite')::boolean and not (item->>'keep_links')::boolean
                           then item->'links' else links end
      where id = found_id;
    end if;
  end loop;
end
$catalogo$;

select sort_order, name, category, subcategory, status, wide as destacado
from projects
order by sort_order, id;
